  1	<!DOCTYPE html>
  2	<html lang="en">
  3	<head>
  4	<meta charset="utf-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1">
  6	<title>Tetris</title>
  7	<style>
  8	  :root {
  9	    --cell: 28px;
 10	    --bg: #14161c;
 11	    --panel: #1e2129;
 12	    --line: #2a2e38;
 13	    --text: #e8eaf0;
 14	    --muted: #9aa0ad;
 15	  }
 16	  * { box-sizing: border-box; }
 17	  body {
 18	    margin: 0;
 19	    min-height: 100vh;
 20	    display: flex;
 21	    align-items: center;
 22	    justify-content: center;
 23	    background: var(--bg);
 24	    color: var(--text);
 25	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
 26	  }
 27	  .game {
 28	    display: flex;
 29	    gap: 20px;
 30	    align-items: flex-start;
 31	    padding: 20px;
 32	  }
 33	  .board-wrap { position: relative; }
 34	  .board {
 35	    display: grid;
 36	    grid-template-columns: repeat(10, var(--cell));
 37	    grid-template-rows: repeat(20, var(--cell));
 38	    gap: 1px;
 39	    padding: 1px;
 40	    background: var(--line);
 41	    border: 2px solid var(--line);
 42	  }
 43	  .cell { background: var(--panel); }
 44	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
 45	  .overlay {
 46	    position: absolute;
 47	    inset: 0;
 48	    display: flex;
 49	    align-items: center;
 50	    justify-content: center;
 51	    background: rgba(0,0,0,0.6);
 52	    font-size: 24px;
 53	    font-weight: 600;
 54	  }
 55	  .side {
 56	    display: flex;
 57	    flex-direction: column;
 58	    gap: 14px;
 59	    min-width: 140px;
 60	  }
 61	  .box {
 62	    background: var(--panel);
 63	    border: 1px solid var(--line);
 64	    padding: 10px 12px;
 65	  }
 66	  .label {
 67	    font-size: 11px;
 68	    text-transform: uppercase;
 69	    letter-spacing: 0.08em;
 70	    color: var(--muted);
 71	  }
 72	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
 73	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
 74	  .mini {
 75	    display: grid;
 76	    grid-template-columns: repeat(4, 16px);
 77	    grid-template-rows: repeat(2, 16px);
 78	    gap: 1px;
 79	  }
 80	  .mini-cell { background: transparent; }
 81	  button {
 82	    font: inherit;
 83	    color: var(--text);
 84	    background: var(--panel);
 85	    border: 1px solid var(--line);
 86	    padding: 8px 12px;
 87	    cursor: pointer;
 88	  }
 89	  button:hover { border-color: var(--muted); }
 90	  .help { font-size: 12px; color: var(--muted); line-height: 1.6; }
 91	  .p-I { background: #22c7e0; }
 92	  .p-O { background: #f2c511; }
 93	  .p-T { background: #9b4dca; }
 94	  .p-S { background: #3cb44b; }
 95	  .p-Z { background: #e6194b; }
 96	  .p-J { background: #2f6fdf; }
 97	  .p-L { background: #f58231; }
 98	</style>
 99	</head>
100	<body>
101	<div class="game">
102	  <div class="board-wrap">
103	    <div class="board" data-testid="board" id="board"></div>
104	  </div>
105	  <div class="side">
106	    <div class="box">
107	      <div class="label">Score</div>
108	      <div class="value" data-testid="score" id="score">0</div>
109	    </div>
110	    <div class="box">
111	      <div class="label">Level</div>
112	      <div class="value" data-testid="level" id="level">1</div>
113	    </div>
114	    <div class="box">
115	      <div class="label">Lines</div>
116	      <div class="value" data-testid="lines" id="lines">0</div>
117	    </div>
118	    <div class="box">
119	      <div class="label">Next</div>
120	      <div class="next-list" data-testid="next-piece" id="next"></div>
121	    </div>
122	    <button type="button" id="new-game">New game</button>
123	    <div class="help">
124	      ← → move<br>
125	      ↓ soft drop<br>
126	      Space hard drop<br>
127	      ↑ rotate
128	    </div>
129	  </div>
130	</div>
131	
132	<script>
133	(function () {
134	  "use strict";
135	
136	  var ROWS = 20;
137	  var COLS = 10;
138	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
139	  var PREVIEW = 3;
140	  var GRAVITY_MS = 1000;
141	  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
142	  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move restarts the delay
143	
144	  // Points for rows cleared at once, times the level. Clearing rows together
145	  // must always beat clearing the same rows one at a time.
146	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
147	  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
148	  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop
149	
150	  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
151	  var SHAPES = {
152	    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
153	    O: { m: ["OO", "OO"], row: 0, col: 4 },
154	    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
155	    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
156	    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
157	    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
158	    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
159	  };
160	
161	  // ---- State ----
162	  var board;        // board[row][col] = "" or piece letter
163	  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
164	  var next;         // upcoming piece letters, soonest first
165	  var scripted;     // true while `next` comes from a test-supplied queue
166	  var bag = [];
167	  var score, level, lines, status;
168	  var timer = null;
169	
170	  function emptyBoard() {
171	    var b = [];
172	    for (var r = 0; r < ROWS; r++) {
173	      var row = [];
174	      for (var c = 0; c < COLS; c++) row.push("");
175	      b.push(row);
176	    }
177	    return b;
178	  }
179	
180	  function randomType() {
181	    if (bag.length === 0) {
182	      bag = TYPES.slice();
183	      for (var i = bag.length - 1; i > 0; i--) {
184	        var j = Math.floor(Math.random() * (i + 1));
185	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
186	      }
187	    }
188	    return bag.pop();
189	  }
190	
191	  function fillPreview() {
192	    if (scripted) return;
193	    while (next.length < PREVIEW) next.push(randomType());
194	  }
195	
196	  function shapeCells(matrix, row, col) {
197	    var cells = [];
198	    for (var r = 0; r < matrix.length; r++) {
199	      for (var c = 0; c < matrix[r].length; c++) {
200	        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
201	      }
202	    }
203	    return cells;
204	  }
205	
206	  function fits(matrix, row, col) {
207	    var cells = shapeCells(matrix, row, col);
208	    for (var i = 0; i < cells.length; i++) {
209	      var r = cells[i][0], c = cells[i][1];
210	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
211	      if (board[r][c] !== "") return false;
212	    }
213	    return true;
214	  }
215	
216	  function spawn() {
217	    if (next.length === 0) scripted = false;
218	    fillPreview();
219	    var type = next.shift();
220	    fillPreview();
221	    var s = SHAPES[type];
222	    var piece = {
223	      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
224	      lockTicks: 0,   // consecutive gravity steps spent unable to fall
225	      lockResets: 0   // lifetime count of lock-delay restarts
226	    };
227	    if (!fits(piece.matrix, piece.row, piece.col)) {
228	      current = null;
229	      status = "gameover";
230	      stopTimer();
231	      return;
232	    }
233	    current = piece;
234	  }
235	
236	  function lock() {
237	    var cells = shapeCells(current.matrix, current.row, current.col);
238	    for (var i = 0; i < cells.length; i++) {
239	      board[cells[i][0]][cells[i][1]] = current.type;
240	    }
241	    current = null;
242	    clearLines();
243	    spawn();
244	  }
245	
246	  // Removes every full row; rows above drop down.
247	  function clearLines() {
248	    var kept = board.filter(function (row) {
249	      return row.some(function (v) { return v === ""; });
250	    });
251	    var cleared = ROWS - kept.length;
252	    if (cleared === 0) return;
253	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
254	    board = kept;
255	    lines += cleared;
256	    score += CLEAR_POINTS[Math.min(cleared, 4)] * level;
257	  }
258	
259	  function tryMove(dr, dc) {
260	    if (!current) return false;
261	    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
262	    current.row += dr;
263	    current.col += dc;
264	    return true;
265	  }
266	
267	  // The single gravity step, used by the real timer, tick() and soft drop.
268	  // A step that cannot move the piece down counts one tick of lock delay.
269	  // Returns true if the piece moved down.
270	  function gravityStep() {
271	    if (status !== "running" || !current) return false;
272	    if (tryMove(1, 0)) {
273	      current.lockTicks = 0;
274	      return true;
275	    }
276	    current.lockTicks++;
277	    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
278	    return false;
279	  }
280	
281	  function softDrop() {
282	    if (gravityStep()) score += SOFT_DROP_POINTS;
283	  }
284	
285	  // Left/right. A move made while the lock delay is running restarts it,
286	  // up to MAX_LOCK_RESETS times per piece.
287	  function shift(dc) {
288	    var resting = current.lockTicks > 0;
289	    if (!tryMove(0, dc)) return;
290	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
291	      current.lockResets++;
292	      current.lockTicks = 0;
293	    }
294	  }
295	
296	  // Clockwise rotation. Tries the rotated shape in place, then shifted
297	  // sideways; if none fit, the piece is left unchanged.
298	  function rotateCW() {
299	    if (!current) return;
300	    var m = current.matrix;
301	    var n = m.length;
302	    var rotated = [];
303	    for (var r = 0; r < n; r++) {
304	      var line = "";
305	      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
306	      rotated.push(line);
307	    }
308	    var kicks = [0, -1, 1, -2, 2];
309	    for (var i = 0; i < kicks.length; i++) {
310	      var nc = current.col + kicks[i];
311	      if (fits(rotated, current.row, nc)) {
312	        current.matrix = rotated;
313	        current.col = nc;
314	        return;
315	      }
316	    }
317	  }
318	
319	  // Hard drop skips the lock delay.
320	  function hardDrop() {
321	    if (!current) return;
322	    while (tryMove(1, 0)) score += HARD_DROP_POINTS;
323	    lock();
324	  }
325	
326	  function applyInput(action) {
327	    if (status !== "running" || !current) return;
328	    switch (action) {
329	      case "left": shift(-1); break;
330	      case "right": shift(1); break;
331	      case "softDrop": softDrop(); break;
332	      case "hardDrop": hardDrop(); break;
333	      case "rotateCW":
334	      case "rotate": rotateCW(); break;
335	    }
336	  }
337	
338	  // ---- Timer ----
339	  function stopTimer() {
340	    if (timer !== null) { clearInterval(timer); timer = null; }
341	  }
342	
343	  function startTimer() {
344	    stopTimer();
345	    timer = setInterval(function () {
346	      gravityStep();
347	      render();
348	    }, GRAVITY_MS);
349	  }
350	
351	  // ---- Rendering (synchronous) ----
352	  var boardEl = document.getElementById("board");
353	  var nextEl = document.getElementById("next");
354	  var boardWrapEl = boardEl.parentNode;
355	  var overlayEl = document.createElement("div");
356	  overlayEl.className = "overlay";
357	  overlayEl.setAttribute("data-testid", "game-over");
358	  overlayEl.textContent = "Game over";
359	  var scoreEl = document.getElementById("score");
360	  var levelEl = document.getElementById("level");
361	  var linesEl = document.getElementById("lines");
362	  var cellEls = [];
363	
364	  (function buildBoard() {
365	    for (var r = 0; r < ROWS; r++) {
366	      cellEls.push([]);
367	      for (var c = 0; c < COLS; c++) {
368	        var el = document.createElement("div");
369	        el.className = "cell";
370	        el.setAttribute("data-testid", "cell");
371	        el.setAttribute("data-row", String(r));
372	        el.setAttribute("data-col", String(c));
373	        el.setAttribute("data-filled", "false");
374	        el.setAttribute("data-piece", "");
375	        boardEl.appendChild(el);
376	        cellEls[r].push(el);
377	      }
378	    }
379	  })();
380	
381	  function paintCell(el, piece) {
382	    el.className = piece ? "cell p-" + piece : "cell";
383	    el.setAttribute("data-filled", piece ? "true" : "false");
384	    el.setAttribute("data-piece", piece);
385	  }
386	
387	  function renderNext() {
388	    nextEl.textContent = "";
389	    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
390	      var type = next[i];
391	      var m = SHAPES[type].m;
392	      var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
393	      var mini = document.createElement("div");
394	      mini.className = "mini";
395	      mini.setAttribute("data-testid", "next-piece-item");
396	      mini.setAttribute("data-piece", type);
397	      for (var r = 0; r < 2; r++) {
398	        for (var c = 0; c < 4; c++) {
399	          var ch = m[r + offset] && m[r + offset][c];
400	          var cell = document.createElement("div");
401	          cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
402	          mini.appendChild(cell);
403	        }
404	      }
405	      nextEl.appendChild(mini);
406	    }
407	  }
408	
409	  function render() {
410	    var view = board.map(function (row) { return row.slice(); });
411	    if (current) {
412	      var cells = shapeCells(current.matrix, current.row, current.col);
413	      for (var i = 0; i < cells.length; i++) {
414	        view[cells[i][0]][cells[i][1]] = current.type;
415	      }
416	    }
417	    for (var r = 0; r < ROWS; r++) {
418	      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c]);
419	    }
420	    scoreEl.textContent = String(score);
421	    levelEl.textContent = String(level);
422	    linesEl.textContent = String(lines);
423	    // The overlay is in the DOM only while the game is over.
424	    if (status === "gameover") {
425	      if (!overlayEl.parentNode) boardWrapEl.appendChild(overlayEl);
426	    } else if (overlayEl.parentNode) {
427	      overlayEl.parentNode.removeChild(overlayEl);
428	    }
429	    renderNext();
430	  }
431	
432	  // ---- Game control ----
433	  function validTypes(queue) {
434	    if (!Array.isArray(queue)) return [];
435	    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
436	  }
437	
438	  function newGame(queue) {
439	    board = emptyBoard();
440	    score = 0;
441	    level = 1;
442	    lines = 0;
443	    status = "running";
444	    current = null;
445	    bag = [];
446	    if (Array.isArray(queue)) {
447	      next = validTypes(queue);
448	      scripted = true;
449	    } else {
450	      next = [];
451	      scripted = false;
452	    }
453	    spawn();
454	    startTimer();
455	    render();
456	  }
457	
458	  function setQueue(queue) {
459	    next = validTypes(queue);
460	    scripted = true;
461	    render();
462	  }
463	
464	  function setBoard(rows) {
465	    var b = emptyBoard();
466	    for (var r = 0; r < ROWS; r++) {
467	      var line = (rows && rows[r]) || "";
468	      for (var c = 0; c < COLS; c++) {
469	        var ch = line.charAt(c);
470	        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
471	      }
472	    }
473	    board = b;
474	    render();
475	  }
476	
477	  function getBoard() {
478	    return board.map(function (row) {
479	      return row.map(function (v) { return v || "."; }).join("");
480	    });
481	  }
482	
483	  function getState() {
484	    var cur = null;
485	    if (current) {
486	      var cells = shapeCells(current.matrix, current.row, current.col);
487	      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
488	      cur = { type: current.type, cells: cells };
489	    }
490	    return {
491	      current: cur,
492	      next: next.slice(),
493	      score: score,
494	      level: level,
495	      lines: lines,
496	      status: status
497	    };
498	  }
499	
500	  function tick(n) {
501	    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
502	    for (var i = 0; i < steps; i++) gravityStep();
503	    render();
504	  }
505	
506	  window.__tetris = {
507	    newGame: newGame,
508	    setQueue: setQueue,
509	    setBoard: setBoard,
510	    tick: tick,
511	    input: function (action) { applyInput(action); render(); },
512	    getBoard: getBoard,
513	    getState: getState
514	  };
515	
516	  // ---- Keyboard ----
517	  var KEYS = {
518	    ArrowLeft: "left",
519	    ArrowRight: "right",
520	    ArrowDown: "softDrop",
521	    " ": "hardDrop",
522	    ArrowUp: "rotateCW"
523	  };
524	
525	  document.addEventListener("keydown", function (e) {
526	    var action = KEYS[e.key];
527	    if (!action) return;
528	    e.preventDefault();
529	    window.__tetris.input(action);
530	  });
531	
532	  document.getElementById("new-game").addEventListener("click", function (e) {
533	    e.currentTarget.blur();
534	    newGame();
535	  });
536	
537	  newGame();
538	})();
539	</script>
540	</body>
541	</html>

