T.tick(1); assert.equal(T.getState().current.type,'O'); T.tick(1); assert.equal(T.getState().current.type,'T','locks after 2 ticks');
// 2: repeated soft drops never lock by themselves, no points at rest
let sc=atBottom(); for(let i=0;i<20;i++) T.input('softDrop'); assert.equal(T.getState().current.type,'O'); assert.equal(T.getState().score,sc);
// 3: cap of 3 restarts shared with sideways
atBottom(); T.tick(1); T.input('left'); T.tick(1); T.input('softDrop'); T.tick(1); T.input('right'); T.tick(1); T.input('softDrop');
assert.equal(T.getState().current.type,'O'); T.tick(1); assert.equal(T.getState().current.type,'T','cap reached, locks');
// 4: soft drop in air scores 1/cell
T.newGame(['O','T']); T.input('softDrop'); assert.equal(T.getState().score,1);
// 5: hard drop instant
T.newGame(['O','T']); T.input('hardDrop'); assert.equal(T.getState().current.type,'T'); assert.equal(T.getState().score,36);
